DECLARE packs jsonb := $pack$[{"codigo":"S22Q-C01","legacy_id":568,"legacy_ids":[568],"relacionadas":[],"residual":"Falta acreditar referencias canónicas de timer visual y cantidad de slots, y reconciliar momento y elegibilidad de fallback SMS con política OTP vigente; no activar fallback por raster.","coberturas":[{"legacy_id":568,"estado_cobertura":"PARCIAL","residual":"Falta acreditar referencias canónicas de timer visual y cantidad de slots, y reconciliar momento y elegibilidad de fallback SMS con política OTP vigente; no activar fallback por raster.","diferencias":"En ONB_002 BLOQUEAR representación incompatible con VD_CLIENT_ONB002_WEB_V06_20260820: título Te enviamos un código, NORMAL con contador sin subrayar y Reenviar código muted/subrayado, COUNTER_EXHAUSTED con reenvío y ¿No te llegó? Enviar por SMS solo si política autoriza, INVALID_CODE con borde error rojo y texto Código incorrecto. Revisa e intenta de nuevo. En todos mantener CTA visual ACTIVE_GREEN, reservar línea de error y conservar H1, CTA y trust row alineados con ONB_001 sin layout shift. Contador y slots derivan de contrato OTP vigente, no cifras de raster; timing y fallback pendientes de reconciliación con REG_RATE_005, REG_SEG_001, REG_SEG_002 y OTP_POL_DEFAULT. No modificar políticas ni habilitar SMS. Binding pendiente."}],"hechos":["s22q01_render_onb002","s22q01_estado_normal_invalido","s22q01_estado_agotado_invalido","s22q01_estado_error_invalido","s22q01_anclaje_o_reserva_invalida","s22q01_timer_o_slots_no_canonicos"],"paquete":{"tipo":"NUEVA","codigo":"S22Q-C01","clave":"s22q_legacy_568","familia":"LOADING_EMPTY_ERROR_STATES","naturaleza":"CONDUCTA","clase":"PANTALLA","alcance":"CLIENT_ONBOARDING","modo":"HEREDA","dueno":"PRODUCTO","titulo":"Estados visuales de OTP con anclaje estable","descripcion":"En ONB_002 BLOQUEAR representación incompatible con VD_CLIENT_ONB002_WEB_V06_20260820: título Te enviamos un código, NORMAL con contador sin subrayar y Reenviar código muted/subrayado, COUN