,"s22q08_selector_grupo_invalido":false,"s22q08_selector_empresa_invalido":true,"s22q08_scope_no_server_o_acceso_cruzado":false,"s22q08_cambio_grupo_efectos_faltan":false,"s22q08_cambio_empresa_efectos_faltan":false},"esperado":true},{"casuistica":"SE_CUMPLE","entrada":{"s22q08_evalua_scope_b2b":true,"s22q08_fusiona_empresas_o_datos":false,"s22q08_identidad_no_canonica":false,"s22q08_selector_grupo_invalido":false,"s22q08_selector_empresa_invalido":false,"s22q08_scope_no_server_o_acceso_cruzado":true,"s22q08_cambio_grupo_efectos_faltan":false,"s22q08_cambio_empresa_efectos_faltan":false},"esperado":true},{"casuistica":"SE_CUMPLE","entrada":{"s22q08_evalua_scope_b2b":true,"s22q08_fusiona_empresas_o_datos":false,"s22q08_identidad_no_canonica":false,"s22q08_selector_grupo_invalido":false,"s22q08_selector_empresa_invalido":false,"s22q08_scope_no_server_o_acceso_cruzado":false,"s22q08_cambio_grupo_efectos_faltan":true,"s22q08_cambio_empresa_efectos_faltan":false},"esperado":true},{"casuistica":"SE_CUMPLE","entrada":{"s22q08_evalua_scope_b2b":true,"s22q08_fusiona_empresas_o_datos":false,"s22q08_identidad_no_canonica":false,"s22q08_selector_grupo_invalido":false,"s22q08_selector_empresa_invalido":false,"s22q08_scope_no_server_o_acceso_cruzado":false,"s22q08_cambio_grupo_efectos_faltan":false,"s22q08_cambio_empresa_efectos_faltan":true},"esperado":true},{"casuistica":"NO_SE_CUMPLE","entrada":{"s22q08_evalua_scope_b2b":false,"s22q08_fusiona_empresas_o_datos":true,"s22q08_identidad_no_canonica":true,"s22q08_selector_grupo_invalido":true,"s22q08_selector_empresa_invalido":true,"s22q08_scope_no_server_o_acceso_cruzado":true,"s22q08_cambio_grupo_efectos_faltan":true,"s22q08_cambio_empresa_efectos_faltan":true},"esperado":false}]},"hash":"9f17ba16ecd9a5feea9a55dda1330077974d791d0b2ae4559d6ecb759222bff2","hash_paquete":"136ea724d18d562fdf9d7d3140ac18cfd60bec64b7dca0e1220affdd499b75dd","hash_evaluado":"9f17ba16ec","hash_paquete_10":"136ea724d1"}]$pack$::jsonb; p jsonb; a jsonb; ans jsonb; cd text; h text; t record; n int:=0; vectors int:=0; b_leg jsonb; b_dep jsonb; b_cfg jsonb; val jsonb; lid int; residual text; diff text; old_desc text; new_desc text; links int:=0; before_replaced int; after_replaced int; direct_hash text; c jsonb;
BEGIN
 SELECT count(DISTINCT legacy_id) INTO before_replaced FROM lf_ops.lf_nucleo_cobertura_legada WHERE estado_cobertura='REEMPLAZADA';
 SELECT jsonb_agg(to_jsonb(x) ORDER BY id) INTO b_leg FROM lf_ops.reglas x;
 SELECT jsonb_agg(to_jsonb(x) ORDER BY regla,version) INTO b_dep FROM lf_ops.nucleo_deprecaciones x;
 SELECT jsonb_agg(to_jsonb(x) ORDER BY to_jsonb(x)::text) INTO b_cfg FROM public.lf_global_config x;
 FOR p IN SELECT value FROM jsonb_array_elements(packs) LOOP
 a:=p->'paquete'; cd:=p->>'codigo';
 IF EXISTS(WITH RECURSIVE anc AS (SELECT codigo,padre FROM lf_ops.nucleo_nodos WHERE pantalla_id=36 UNION ALL SELECT nn.codigo,nn.padre FROM lf_ops.nucleo_nodos nn JOIN anc z ON nn.codigo=z.padre) SELECT 1 FROM anc WHERE codigo=a->>'alcance') THEN RAISE EXCEPTION 'S22_SCOPE_P36 %',cd; END IF;
 ans:=lf_ops.nucleo_regla_proponer_v1(a,true);
 IF ans->>'resultado' IS DISTINCT FROM 'CANDIDATA' OR (ans->>'version')::int IS DISTINCT FROM 1 THEN RAISE EXCEPTION 'S22_PROPOSAL_FAIL % %',cd,ans; END IF;
 ans:=lf_ops.nucleo_regla_evaluar_v1(cd,true); h:=lf_ops.nucleo_hash_paquete_v1(cd,1);
 IF h IS DISTINCT FROM p->>'hash_paquete' OR NOT EXISTS(SELECT 1 FROM lf_ops.nucleo_regla_versiones WHERE regla=cd AND version=1 AND estado='CANDIDATA' AND hash=p->>'hash') THEN RAISE EXCEPTION 'S22_ATTESTATION_DRIFT %',cd; END IF;
 FOR t IN SELECT entrada,esperado FROM lf_ops.nucleo_regla_pruebas WHERE regla=cd AND version=1 LOOP
 IF lf_ops.nucleo_eval_v1(a->'condicion',t.entrada) IS DISTINCT FROM t.esperado THEN RAISE EXCEPTION 'S22_VECTOR_FAIL %',cd; END IF; vectors:=vectors+1; END LOOP;
 n:=n+1;
 END LOOP;
 IF n<>8 OR vectors<>54 THEN RAISE EXCEPTION 'S22_VECTOR_COUNT'; END IF;
 IF (SELECT jsonb_agg(to_jsonb(x) ORDER BY id) FROM lf_ops.reglas x) IS DISTINCT FROM b_leg OR (SELECT jsonb_agg(to_jsonb(x) ORDER BY regla,version) FROM lf_ops.nucleo_deprecaciones x) IS DISTINCT FROM b_dep OR (SELECT jsonb_agg(to_jsonb(x) ORDER BY to_jsonb(x)::text) FROM public.lf_global_config x) IS DISTINCT FROM b_cfg THEN RAISE EXCEPTION 'S22_INVARIANT_FAIL'; END IF;
 IF jsonb_array_length(lf_ops.lf_nucleo_lectura_transicion_v1(36,'INPUT_GOVERNANCE','DIRECTAS')->'nativas') IS DISTINCT FROM 0 THEN RAISE EXCEPTION 'S22_DPIG03_FAIL'; END IF;
 RAISE NOTICE 'S22Q proposal-only: independent judgment pending';
END $s22$;
COMMIT;
